import { test, expect } from '@playwright/test';
import { prepareReadOnly, openHome, stripOpensFilters } from './search-cta.helpers';

test.use({ serviceWorkers: 'block' });

test('Главная: после прокрутки полоса «חפש עסק», нажатие открывает поиск с фильтрами #1a3a08 #839121 @android @prod-safe', async ({ page, context }) => {
  await prepareReadOnly(context);
  await openHome(page);
  const dialog = await stripOpensFilters(page);
  await expect(dialog.getByPlaceholder('חפש עסק לפי שם, תיאור או מיקום...'), 'в окне есть текстовый поиск').toBeVisible();
});
